void* ReadMLUStructure(struct _cms_typehandler_struct* self, cmsIOHANDLER* io, cmsUInt32Number* nItems, cmsUInt32Number SizeOfTag) {
    cmsMLU* mlu = NULL;
    cmsUInt32Number count = 0, recordLength = 0, i;
    cmsUInt32Number langCodeLen = 0, countryLen = 0, strLen = 0;
    cmsUInt32Number maxPos = 0;
    cmsUInt8Number* buffer = NULL;

    if (!io || !nItems) return NULL;

    if (!io->Read(io, &count, sizeof(cmsUInt32Number), 1)) goto error;
    if (!io->Read(io, &recordLength, sizeof(cmsUInt32Number), 1)) goto error;

    if (recordLength != 8) goto error;

    mlu = (cmsMLU*)calloc(1, sizeof(cmsMLU));
    if (!mlu) goto error;

    mlu->Count = count;
    mlu->Entries = (cmsMLUentry*)calloc(count, sizeof(cmsMLUentry));
    if (!mlu->Entries) goto error;

    for (i = 0; i < count; i++) {
        if (!io->Read(io, &mlu->Entries[i].LanguageCode, sizeof(cmsUInt16Number), 1) ||
            !io->Read(io, &mlu->Entries[i].CountryCode, sizeof(cmsUInt16Number), 1) ||
            !io->Read(io, &mlu->Entries[i].StringOffset, sizeof(cmsUInt32Number), 1) ||
            !io->Read(io, &mlu->Entries[i].StringLength, sizeof(cmsUInt32Number), 1))
            goto error;

        maxPos = mlu->Entries[i].StringOffset + mlu->Entries[i].StringLength;
    }

    buffer = (cmsUInt8Number*)calloc(1, maxPos + 1);
    if (!buffer) goto error;

    if (io->Seek(io, mlu->Entries[0].StringOffset) != mlu->Entries[0].StringOffset)
        goto error;

    if (!io->Read(io, buffer, maxPos, 1)) goto error;

    for (i = 0; i < count; i++) {
        mlu->Entries[i].String = (char*)malloc(mlu->Entries[i].StringLength + 1);
        if (!mlu->Entries[i].String) goto error;

        memcpy(mlu->Entries[i].String, buffer + mlu->Entries[i].StringOffset, mlu->Entries[i].StringLength);
        mlu->Entries[i].String[mlu->Entries[i].StringLength] = '\0';
    }

    *nItems = 1;
    free(buffer);
    return (void*)mlu;

error:
    if (buffer) free(buffer);
    if (mlu) {
        for (i = 0; i < count; i++) {
            if (mlu->Entries[i].String) free(mlu->Entries[i].String);
        }
        free(mlu->Entries);
    }
    free(mlu);
    return NULL;
}

void* ReadMLUFromStream(struct _cms_typehandler_struct* self, cmsIOHANDLER* io, cmsUInt32Number* nItems, cmsUInt32Number SizeOfTag)
{
    cmsUInt32Number Count, RecordLength;
    cmsUInt32Number i;
    cmsMLU* Mlu = NULL;
    cmsUInt32Number MaxPos = 0;
    cmsUInt32Number LangCode[2];
    cmsUInt32Number StringLength;
    cmsUInt32Number Offset;

    if (!io->Read(io, &Count, sizeof(cmsUInt32Number), 1) ||
        !io->Read(io, &RecordLength, sizeof(cmsUInt32Number), 1)) {
        goto Error;
    }

    if (RecordLength != 4 && RecordLength != 8) {
        goto Error;
    }

    Mlu = (cmsMLU*)calloc(1, sizeof(cmsMLU));
    if (!Mlu) {
        goto Error;
    }

    Mlu->Count = Count;
    Mlu->RecordLength = RecordLength;
    Mlu->LangCode = (cmsUInt32Number*)calloc(Count, 2 * sizeof(cmsUInt32Number));
    Mlu->StringLength = (cmsUInt32Number*)malloc(Count * sizeof(cmsUInt32Number));
    Mlu->Strings = (char**)malloc(Count * sizeof(char*));

    if (!Mlu->LangCode || !Mlu->StringLength || !Mlu->Strings) {
        goto Error;
    }

    for (i = 0; i < Count; i++) {

        if (!io->Read(io, &LangCode[0], 2 * sizeof(cmsUInt32Number), 1)) {
            goto Error;
        }

        Mlu->LangCode[2 * i]     = LangCode[0];
        Mlu->LangCode[2 * i + 1] = LangCode[1];

        if (!io->Read(io, &StringLength, sizeof(cmsUInt32Number), 1)) {
            goto Error;
        }

        Mlu->StringLength[i] = StringLength;
        Mlu->Strings[i] = (char*)malloc(StringLength + 1);
        if (!Mlu->Strings[i]) {
            goto Error;
        }

        MaxPos = MAX(MaxPos, StringLength);
    }

    if (!io->Seek(io, MaxPos)) {
        goto Error;
    }

    for (i = 0; i < Count; i) {
        if (!io->Read(io, Mlu->Strings[i], Mlu->StringLength[i], 1)) {
            goto Error;
        }
        Mlu->Strings[i][Mlu->StringLength[i]] = '\0';
        i++;
    }

    *nItems = Count;

    return (void*)Mlu;

Error:
    if (Mlu) {
        for (i = 0; i < Count; i++) {
            if (Mlu->Strings[i])
                free(Mlu->Strings[i]);
        }
        free(Mlu->LangCode);
        free(Mlu->StringLength);
        free(Mlu->Strings);
        free(Mlu);
    }

    return NULL;
}

cmsMLU* ReadMLUFromStream(struct _cms_typehandler_struct* self, cmsIOHANDLER* io, cmsUInt32Number* nItems, cmsUInt32Number SizeOfTag) {
    cmsUInt16Number Count;
    cmsUInt16Number RecordLength;
    cmsUInt32Number MaxPos = 0;
    cmsUInt32Number i;
    cmsMLU* mlu;

    if (!io->Read16(io, &Count) || !io->Read16(io, &RecordLength))
        return NULL;

    if (RecordLength != 4)
        return NULL;

    mlu = (cmsMLU*) calloc(1, sizeof(cmsMLU));
    if (!mlu)
        return NULL;

    mlu->Count = Count;
    mlu->RecordLength = RecordLength;
    mlu->Data = (cmsMLUData*) calloc(Count, sizeof(cmsMLUData));
    if (!mlu->Data) {
        free(mlu);
        return NULL;
    }

    for (i = 0; i < Count; i++) {
        cmsUInt16Number Language;
        cmsUInt16Number Country;
        cmsUInt32Number StringLength;
        cmsUInt32Number StringOffset;

        if (!io->Read16(io, &Language) ||
            !io->Read16(io, &Country) ||
            !io->Read32(io, &StringLength) ||
            !io->Read32(io, &StringOffset)) {
            for (cmsUInt32Number j = 0; j < i; j++)
                free(mlu->Data[j].String);
            free(mlu->Data);
            free(mlu);
            return NULL;
        }

        mlu->Data[i].Language = Language;
        mlu->Data[i].Country = Country;
        mlu->Data[i].StringLength = StringLength;
        mlu->Data[i].StringOffset = StringOffset;

        if (StringOffset + StringLength > MaxPos)
            MaxPos = StringOffset + StringLength;
    }

    mlu->Strings = (char*) malloc(MaxPos);
    if (!mlu->Strings) {
        for (i = 0; i < Count; i++)
            free(mlu->Data[i].String);
        free(mlu->Data);
        free(mlu);
        return NULL;
    }

    for (i = 0; i < Count; i++) {
        mlu->Data[i].String = mlu->Strings + mlu->Data[i].StringOffset;
        if (!io->Read(io, mlu->Data[i].String, mlu->Data[i].StringLength)) {
            for (cmsUInt32Number j = 0; j < i; j++)
                free(mlu->Data[j].String);
            free(mlu->Strings);
            free(mlu->Data);
            free(mlu);
            return NULL;
        }
    }

    *nItems = 1;
    return mlu;
}

cmsMLU* ReadMLUFromStream(struct _cms_typehandler_struct* self, cmsIOHANDLER* io, cmsUInt32Number* nItems, cmsUInt32Number SizeOfTag) {
    cmsUInt32Number Count = 0;
    cmsUInt32Number RecordLength = 0;
    cmsUInt32Number i;
    cmsMLU* mlu = NULL;
    cmsUInt16Number* Lang = NULL;
    cmsUInt16Number* Country = NULL;
    cmsUInt32Number* StringLength = NULL;
    cmsUInt32Number* StringOffset = NULL;
    cmsUInt32Number MaxPos = 0;
    cmsUInt8Number* Strings = NULL;
    cmsUInt32Number TotalSize;

    if (!io->Read(io, &Count, sizeof(cmsUInt32Number), 1))
        goto Error;

    if (!io->Read(io, &RecordLength, sizeof(cmsUInt32Number), 1))
        goto Error;

    if (RecordLength != 8)
        goto Error;

    mlu = (cmsMLU*)calloc(1, sizeof(cmsMLU));
    if (!mlu)
        goto Error;

    mlu->nItems = Count;
    mlu->Lang = (cmsUInt16Number*)calloc(Count, sizeof(cmsUInt16Number));
    mlu->Country = (cmsUInt16Number*)calloc(Count, sizeof(cmsUInt16Number));
    mlu->StringLength = (cmsUInt32Number*)calloc(Count, sizeof(cmsUInt32Number));
    mlu->StringOffset = (cmsUInt32Number*)calloc(Count, sizeof(cmsUInt32Number));
    mlu->Strings = NULL;

    if (!mlu->Lang || !mlu->Country || !mlu->StringLength || !mlu->StringOffset)
        goto Error;

    for (i = 0; i < Count; i++) {
        if (!io->Read(io, &mlu->Lang[i], sizeof(cmsUInt16Number), 1))
            goto Error;

        if (!io->Read(io, &mlu->Country[i], sizeof(cmsUInt16Number), 1))
            goto Error;

        if (!io->Read(io, &mlu->StringLength[i], sizeof(cmsUInt32Number), 1))
            goto Error;

        if (!io->Read(io, &mlu->StringOffset[i], sizeof(cmsUInt32Number), 1))
            goto Error;

        if (mlu->StringOffset[i] + mlu->StringLength[i] > MaxPos)
            MaxPos = mlu->StringOffset[i] + mlu->StringLength[i];
    }

    if (MaxPos > 0) {
        mlu->Strings = (cmsUInt8Number*)calloc(1, MaxPos);
        if (!mlu->Strings)
            goto Error;

        if (!io->Read(io, mlu->Strings, 1, MaxPos))
            goto Error;
    }

    *nItems = Count;
    return (void*)mlu;

Error:
    if (mlu) {
        if (mlu->Lang) free(mlu->Lang);
        if (mlu->Country) free(mlu->Country);
        if (mlu->StringLength) free(mlu->StringLength);
        if (mlu->StringOffset) free(mlu->StringOffset);
        if (mlu->Strings) free(mlu->Strings);
        free(mlu);
    }
    *nItems = 0;
    return NULL;
}

void* ReadMLUFromStream(struct _cms_typehandler_struct* self, cmsIOHANDLER* io, cmsUInt32Number* nItems, cmsUInt32Number SizeOfTag)
{
    cmsUInt32Number Count, RecordLen;
    cmsMLU* mlu = NULL;
    cmsUInt32Number i, MaxPos = 0;
    cmsUInt16Number* LangCountry = NULL;
    cmsUInt32Number* StringLengths = NULL;
    cmsUInt32Number* StringOffsets = NULL;
    char* Strings = NULL;

    if (io->Read(io, &Count, sizeof(cmsUInt32Number), 1) != 1 ||
        io->Read(io, &RecordLen, sizeof(cmsUInt32Number), 1) != 1)
        goto Error;

    if (RecordLen != 8) {
        cmsSignalError(self->Context, cmsERR_CORRUPTED_DATA, "Invalid record length in MLU");
        goto Error;
    }

    mlu = (cmsMLU*)calloc(1, sizeof(cmsMLU));
    if (!mlu)
        goto Error;

    LangCountry = (cmsUInt16Number*)malloc(Count * 4);
    if (!LangCountry)
        goto Error;

    StringLengths = (cmsUInt32Number*)malloc(Count * sizeof(cmsUInt32Number));
    if (!StringLengths)
        goto Error;

    StringOffsets = (cmsUInt32Number*)malloc(Count * sizeof(cmsUInt32Number));
    if (!StringOffsets)
        goto Error;

    for (i = 0; i < Count; i++) {
        if (io->Read(io, &LangCountry[i * 2], sizeof(cmsUInt16Number), 2) != 2)
            goto Error;
        if (io->Read(io, &StringLengths[i], sizeof(cmsUInt32Number), 1) != 1)
            goto Error;
        if (io->Read(io, &StringOffsets[i], sizeof(cmsUInt32Number), 1) != 1)
            goto Error;

        MaxPos = cmsMAX(MaxPos, StringOffsets[i] + StringLengths[i]);
    }

    mlu->nItems = Count;
    mlu->LangCountry = LangCountry;
    mlu->StringLengths = StringLengths;
    mlu->StringOffsets = StringOffsets;
    mlu->Data = (char*)malloc(MaxPos);
    if (!mlu->Data)
        goto Error;

    for (i = 0; i < Count; i++) {
        cmsUInt32Number Pos = StringOffsets[i];

        if (io->Seek(io, Pos, 0) != Pos)
            goto Error;

        if (io->Read(io, mlu->Data + Pos, StringLengths[i], 1) != 1)
            goto Error;
    }

    *nItems = 1;
    return (void*)mlu;

Error:
    if (mlu) {
        if (mlu->Data)
            free(mlu->Data);
        free(mlu);
    }
    if (LangCountry)
        free(LangCountry);
    if (StringLengths)
        free(StringLengths);
    if (StringOffsets)
        free(StringOffsets);
    *nItems = 0;
    return NULL;
}
